    public int search(int[] nums, int target) {
        int lo = 0, hi = nums.length - 1;       // 闭区间 [lo, hi] 是还没排除的范围
        while (lo <= hi) {                      // 区间不空就继续
            int mid = lo + (hi - lo) / 2;       // 不写 (lo + hi) / 2，防止溢出
            if (nums[mid] == target) {
                return mid;
            }
            if (nums[mid] < target) {
                lo = mid + 1;                   // mid 和它左边都太小
            } else {
                hi = mid - 1;                   // mid 和它右边都太大
            }
        }
        return -1;
    }
}

