class Solution:
    def countTarget(self, scores: List[int], target: int) -> int:
        def lower_bound(x: int) -> int:     # 第一个 >= x 的位置
            lo, hi = 0, len(scores)         # 左闭右开 [lo, hi)
            while lo < hi:
                mid = (lo + hi) // 2
                if scores[mid] < x:
                    lo = mid + 1            # mid 太小，一定不是答案
                else:
                    hi = mid                # mid 可能就是答案，留在区间里
            return lo
        left = lower_bound(target)          # target 第一次出现的位置
        right = lower_bound(target + 1)     # 第一个比 target 大的位置
        return right - left

