class Solution {
    // 第一个 >= x 的位置，没有就是 nums.length
    private int lowerBound(int[] nums, int x) {
        int lo = 0, hi = nums.length;           // 左闭右开 [lo, hi)
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] < x) {
                lo = mid + 1;                   // mid 太小，一定不是答案
            } else {
                hi = mid;                       // mid 可能就是答案，留在区间里
            }
        }
        return lo;
    }

    public int countTarget(int[] scores, int target) {
        int left = lowerBound(scores, target);          // target 第一次出现的位置
        int right = lowerBound(scores, target + 1);     // 第一个比 target 大的位置
        return right - left;
    }
}

