        lo, hi = 1, max(piles)              # 答案一定在 [lo, hi] 里
        while lo < hi:
            mid = (lo + hi) // 2
            if hours(mid) <= h:             # 吃得完：答案是 mid 或更小
                hi = mid
            else:                           # 吃不完：要更快
                lo = mid + 1
