class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int lo = 1, hi = Arrays.stream(piles).max().getAsInt();    // 答案一定在 [lo, hi] 里
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (hours(piles, mid) <= h) {       // 吃得完：答案是 mid 或更小
                hi = mid;
            } else {                            // 吃不完：要更快
                lo = mid + 1;
            }
        }
        return lo;
    }

    // 速度为 k 时要吃几小时；总数可能超过 int，用 long
    private long hours(int[] piles, int k) {
        long total = 0;
        for (int p : piles) {
            total += (p + k - 1) / k;
        }
        return total;
    }
}

